rule.example:
class Bad {
    fun copy(src: IntArray, dst: IntArray) {
        for (i in src.indices) {
            dst[i] = src[i]   // violation: use src.copyInto(dst)
        }
    }
}

class Good {
    fun copy(src: IntArray, dst: IntArray) {
        src.copyInto(dst)     // ok: built-in efficient copy
    }
    fun copyPartial(src: IntArray): IntArray {
        return src.copyOf()   // ok: returns a new copy
    }
}

import java.util.Calendar
import java.time.LocalDateTime

class Bad {
    fun currentMillis(): Long {
        return Calendar.getInstance().timeInMillis  // violation
    }
}

class Good {
    fun currentMillis(): Long {
        return System.currentTimeMillis()  // ok: no Calendar created
    }

    fun now(): LocalDateTime {
        return LocalDateTime.now()  // ok: java.time API
    }
}

class Bad {
    fun afterBulkLoad() {
        System.gc()                     // violation: unpredictable, may degrade throughput
        Runtime.getRuntime().gc()       // violation: same issue
    }
}

class Good {
    fun afterBulkLoad() {
        // ok: trust the JVM garbage collector; add metrics/monitoring instead
    }
}

import java.io.File
import java.io.FileInputStream
import java.nio.file.Files

class Bad {
    fun read(file: File): ByteArray {
        return FileInputStream(file).readBytes() // violation: use finalizer-free alternative
    }
}

class Good {
    fun read(file: File): ByteArray {
        return file.inputStream().use { it.readBytes() } // ok: extension function, no finalizer
    }

    fun readNio(file: File): ByteArray {
        return Files.newInputStream(file.toPath()).use { it.readBytes() } // ok: NIO approach
    }
}

class Bad {
    fun buildMessage(prefix: String, value: Int): String {
        val sb = StringBuilder()
        sb.append(prefix + ": " + value)  // violation: intermediate String created
        return sb.toString()
    }
}

class GoodChain {
    fun buildMessage(prefix: String, value: Int): String {
        val sb = StringBuilder()
        sb.append(prefix).append(": ").append(value)  // ok: chained appends
        return sb.toString()
    }
}

class GoodBuildString {
    fun buildMessage(prefix: String, value: Int): String =
        buildString {                          // ok: Kotlin idiomatic builder
            append(prefix)
            append(": ")
            append(value)
        }
}

class Bad {
    fun bad(): String {
        return String("hello") // violation: unnecessary String constructor call
    }
}

class Good {
    fun good(): String {
        return "hello" // ok: use the string literal directly
    }
}

class Bad {
    fun bad(name: String): String {
        return name.toString() // violation: toString() on a String is a no-op
    }
}

class Good {
    fun good(name: String): String {
        return name // ok: use the String variable directly
    }
}

// violation: condition-only when with 2 branches -- use if/else instead
fun describeSmall(x: Int): String {
    return when {
        x == 0 -> "zero"
        else   -> "non-zero"
    }
}

// ok: condition-only when with 3 branches justifies using when
fun describeSign(x: Int): String {
    return when {
        x < 0  -> "negative"
        x == 0 -> "zero"
        else   -> "positive"
    }
}

// ok: typed subject -- idiomatic exhaustive matching on sealed/enum, always allowed
fun describe(type: AppType): String {
    return when (type) {
        AppType.GAME -> "game"
        else         -> "other"
    }
}

